(() => {
const $=id=>document.getElementById(id);
const families={
 resistor:{name:'电阻',sub:'贴片电阻',value:'阻值',values:['4.7kΩ','10kΩ','1kΩ','0Ω'],power:'功率',powers:['100mW','125mW','250mW'],extra:'温度系数',extras:['±100ppm/℃','±200ppm/℃'],rows:[['C23162','0603WAF4701T5E','UNI-ROYAL','0603','4.7kΩ','±1%','100mW',5942400,.0028],['C99782','RC0603FR-074K7L','YAGEO','0603','4.7kΩ','±1%','100mW',8781300,.0032],['C2907034','FRC0603F4701TS','FOJAN','0603','4.7kΩ','±1%','100mW',4096600,.0022],['C25999','0603WAJ0472T5E','UNI-ROYAL','0603','4.7kΩ','±5%','100mW',5447000,.0018],['C25900','0402WGF4701TCE','UNI-ROYAL','0402','4.7kΩ','±1%','62.5mW',1810000,.002],['C17673','0805W8F4701T5E','UNI-ROYAL','0805','4.7kΩ','±1%','125mW',950000,.003],['C25804','0603WAF1002T5E','UNI-ROYAL','0603','10kΩ','±1%','100mW',1650000,.0025],['C21190','0603WAF1001T5E','UNI-ROYAL','0603','1kΩ','±1%','100mW',480000,.0025]]},
 capacitor:{name:'电容',sub:'陶瓷电容',value:'容值',values:['100nF','1uF','10uF'],power:'耐压',powers:['16V','25V','50V'],extra:'介质',extras:['X7R','X5R','C0G'],rows:[['C14663','CC0603KRX7R9BB104','YAGEO','0603','100nF','±10%','50V',2100000,.007],['C1591','CL10B104KB8NNNC','Samsung','0603','100nF','±10%','50V',1800000,.006],['C307331','GRM188R71H104KA93','Murata','0603','100nF','±10%','50V',860000,.012],['C1525','CL05B104KO5NNNC','Samsung','0402','100nF','±10%','16V',520000,.005],['C15849','CL21B104KBCNNNC','Samsung','0805','100nF','±10%','50V',980000,.009],['C15850','CL10A105KO8NNNC','Samsung','0603','1uF','±10%','16V',880000,.008]]},
 inductor:{name:'电感 / 线圈',sub:'固定电感',value:'感值',values:['4.7uH','10uH'],power:'额定电流',powers:['350mA','620mA','1A'],extra:'屏蔽类型',extras:['屏蔽','非屏蔽'],rows:[['C114862','LQM18PN4R7MFRL','Murata','0603','4.7uH','±20%','620mA',510000,.08],['C76799','MLF1608E4R7KT','TDK','0603','4.7uH','±10%','350mA',820000,.06],['C42455247','MWSA0603-4R7MT','Sunlord','0603','4.7uH','±20%','1A',160000,.09],['C16791','LQH32CN4R7M23','Murata','1210','4.7uH','±20%','620mA',76000,.11]]},
 ic:{name:'集成电路',sub:'单片机 / 微控制器',value:'内核',values:['ARM Cortex-M0+','ARM Cortex-M3'],power:'工作电压',powers:['1.8V~3.3V','2V~3.6V'],extra:'接口',extras:['USB / SPI / I²C','CAN / USART'],rows:[['C2040','RP2040','Raspberry Pi','QFN-56','ARM Cortex-M0+','双核','1.8V~3.3V',42777,1.08],['C8734','STM32F103C8T6','ST','LQFP-48','ARM Cortex-M3','单核','2V~3.6V',18500,1.21]]}
};
let family='resistor',draft={value:'4.7kΩ',package:'0603',tolerance:'',power:'',brand:'',extra:'',temp:'',stock:'',cad:''},applied=null,rows=[],selected=null,page=1,tab='footprint',zoom=1,querySeq=0,detailSeq=0,task=null;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function field(key,label,values){return `<div class="field"><label for="f-${key}">${label}</label><select id="f-${key}" data-field="${key}"><option value="">全部${label}</option>${[...new Set(values)].map(v=>`<option${draft[key]===v?' selected':''}>${esc(v)}</option>`).join('')}</select></div>`;}
function fields(){const f=families[family];$('fields').innerHTML=field('value',f.value,f.values)+field('package','封装',f.rows.map(r=>r[3]))+field('tolerance',family==='ic'?'核心配置':'精度',f.rows.map(r=>r[5]))+field('power',f.power,f.powers)+field('brand','品牌',f.rows.map(r=>r[2]));$('extra').innerHTML=field('extra',f.extra,f.extras)+field('temp','工作温度',['-55℃~125℃','-40℃~85℃'])+field('stock','供货状态',['仅有库存'])+field('cad','CAD 资料',['有符号及封装','有 3D 模型']);document.querySelectorAll('[data-field]').forEach(s=>s.onchange=()=>{draft[s.dataset.field]=s.value;chips();});$('crumb').innerHTML=`${f.name} / <strong>${f.sub}</strong>`;$('valuehead').textContent=(applied?families[applied.family]:f).value;chips();}
function labels(){const f=families[family];return {value:f.value,package:'封装',tolerance:family==='ic'?'核心配置':'精度',power:f.power,brand:'品牌',extra:f.extra,temp:'工作温度',stock:'供货状态',cad:'CAD 资料'};}
function chips(){const names=labels();$('chips').innerHTML=Object.entries(draft).filter(([k,v])=>v).map(([k,v])=>`<button class="chip" data-clear="${k}" aria-label="移除${names[k]}">${names[k]} ${esc(v)}<i>×</i></button>`).join('');document.querySelectorAll('[data-clear]').forEach(b=>b.onclick=()=>{draft[b.dataset.clear]='';fields();});$('dirty').textContent=applied&&JSON.stringify({family,keyword:$('keyword').value,draft})!==applied.signature?'条件有修改，点击查询应用':'';}
function categories(){const list=Object.entries(families).map(([key,f])=>`<button class="category ${family===key?'active':''}" data-family="${key}">${f.name}</button>${family===key?`<div class="subcat">└ ${f.sub}</div>`:''}`).join('');$('categorylist').innerHTML=list+'<button class="category" data-unavailable>二极管</button><button class="category" data-unavailable>连接器</button>';$('mobilecategory').innerHTML=Object.entries(families).map(([k,f])=>`<option value="${k}"${family===k?' selected':''}>${f.name}</option>`).join('');document.querySelectorAll('[data-family]').forEach(b=>b.onclick=()=>changeFamily(b.dataset.family));document.querySelectorAll('[data-unavailable]').forEach(b=>b.onclick=()=>inform('此原型展示电阻、电容、电感和单片机四类','正式版按上游类目动态提供参数。'));}
function changeFamily(key){stopTask();querySeq++;detailSeq++;$('query').disabled=false;family=key;draft={value:'',package:'',tolerance:'',power:'',brand:'',extra:'',temp:'',stock:'',cad:''};$('keyword').value='';categories();fields();$('dirty').textContent='分类已修改，点击查询加载';}
function normalKeyword(kw,fam){kw=kw.trim().toLowerCase().replace(/\s/g,'').replace(/µ|μ/g,'u').replace(/ohms?/g,'ω');if(fam==='resistor'&&/^(4\.7k(?:ω)?|4k7|4700ω)$/.test(kw))return '4.7kω';if(fam==='capacitor'&&/^(0\.1uf|100nf|100000pf)$/.test(kw))return '100nf';if(fam==='inductor'&&/^(4\.7uh|4700nh)$/.test(kw))return '4.7uh';return kw;}
function startTask(title,sub,cancel){stopTask();const start=Date.now();task={timer:setInterval(()=>{$('tasktitle').textContent=title+' · '+Math.floor((Date.now()-start)/1000)+' 秒';if(Date.now()-start>5000)$('tasksub').textContent='耗时较长，条件已保留。你可以继续查看详情或取消等待。';},500),cancel};$('tasktitle').textContent=title;$('tasksub').textContent=sub;$('cancel').style.display=cancel?'':'none';$('toast').style.display='block';$('footstatus').textContent=title;}
function stopTask(){if(task)clearInterval(task.timer);task=null;$('toast').style.display='none';}
function inform(title,sub){startTask(title,sub,null);const token=task;setTimeout(()=>{if(task===token)stopTask();},3200);}
function draw(){$('valuehead').textContent=families[applied?applied.family:family].value;const start=(page-1)*6;let sorted=rows.slice().sort((a,b)=>$('sort').value==='stock'?b[7]-a[7]:a[8]-b[8]);$('rows').innerHTML=sorted.slice(start,start+6).map(r=>`<tr data-cid="${r[0]}" class="${selected&&selected[0]===r[0]?'selected':''}"><td><b>${r[1]}</b><small>${r[0]}</small></td><td>${r[2]}</td><td>${r[3]}</td><td>${r[4]}</td><td class="optcol">${r[5]}</td><td class="stock">${r[7].toLocaleString()}</td></tr>`).join('');$('total').textContent=rows.length+' 个示例器件';$('pagesummary').textContent=`每页 6 条 · 共 ${rows.length} 条`;$('pageno').textContent=page;$('prev').disabled=page<=1;$('next').disabled=page*6>=rows.length;$('emptystate').innerHTML=rows.length?'':'<div class="noresults">当前条件没有匹配器件<br>尝试清除封装或精度条件，再点击查询。</div>';document.querySelectorAll('[data-cid]').forEach(tr=>{tr.onclick=()=>{selected=rows.find(r=>r[0]===tr.dataset.cid);details();draw();};tr.ondblclick=()=>place();});}
function query(){if($('query').disabled)return;const seq=++querySeq;const snapshot={family,keyword:$('keyword').value,draft:{...draft}};const scenario=$('scenario').value;const signature=JSON.stringify(snapshot);$('query').disabled=true;$('query').textContent='查询中';$('emptystate').innerHTML='';$('rows').innerHTML=Array.from({length:6},()=>'<tr>'+Array.from({length:6},(_,i)=>`<td><span class="skeleton ${i===0?'long':''}"></span>${i===0?'<span class="skeleton" style="width:40%"></span>':''}</td>`).join('')+'</tr>').join('');$('applied').textContent='正在查询 '+families[snapshot.family].sub+' · 条件已锁定';startTask('正在查询器件','正在按分类、数值与封装筛选；完成前可继续编辑条件。',()=>{querySeq++;$('query').disabled=false;$('query').textContent='查询';stopTask();draw();$('applied').textContent=applied?applied.label:'查询已取消，尚无已应用结果';});setTimeout(()=>{if(seq!==querySeq)return;$('query').disabled=false;$('query').textContent='查询';stopTask();if(scenario==='error'){$('rows').innerHTML='';$('emptystate').innerHTML='<div class="failure"><b>暂时无法取得商城结果</b><br>筛选条件已保留，请检查网络后重试。<br><button id="retry">重试查询</button></div>';$('retry').onclick=()=>{$('scenario').value='normal';query();};$('applied').textContent='查询失败 · 未应用新的结果';$('footstatus').textContent='查询失败，条件已保留';return;}const kw=normalKeyword(snapshot.keyword,snapshot.family);const d=snapshot.draft;rows=scenario==='empty'?[]:families[snapshot.family].rows.filter(r=>(!kw||[r[0],r[1],r[2],r[4]].some(v=>normalKeyword(v,snapshot.family).includes(kw)))&&(!d.value||r[4]===d.value)&&(!d.package||r[3]===d.package)&&(!d.tolerance||r[5]===d.tolerance)&&(!d.power||r[6]===d.power)&&(!d.brand||r[2]===d.brand)&&(!d.extra||d.extra===families[snapshot.family].extras[0])&&(!d.temp||d.temp==='-55℃~125℃')&&(!d.stock||r[7]>0)&&(!d.cad||d.cad==='有符号及封装'));applied={...snapshot,signature,label:families[snapshot.family].sub+' · '+(snapshot.keyword||'全部关键词')+' · '+Object.entries(d).filter(([k,v])=>v).map(([k,v])=>v).join(' / ')};$('applied').textContent=applied.label;page=1;selected=rows[0]||null;draw();details();chips();$('footstatus').textContent='查询完成 · '+rows.length+' 个示例器件';},scenario==='slow'?8000:1100);}
function art(kind){const isIC=selected&&selected[0]==='C2040';if(kind==='symbol')return '<svg viewBox="0 0 320 210" aria-label="示例电阻符号"><g fill="none" stroke="#447188" stroke-width="2"><path d="M35 105h65m0-15h120v30H100zm120 15h65"/><circle cx="35" cy="105" r="3"/><circle cx="285" cy="105" r="3"/></g><g fill="#6d8494" font-family="Arial" font-size="12"><text x="147" y="70">R?</text><text x="142" y="151">'+esc(selected?selected[4]:'')+'</text><text x="62" y="96">1</text><text x="250" y="96">2</text></g></svg>';if(kind==='3d')return '<svg viewBox="0 0 320 210" aria-label="示意模型，非真实器件模型"><g transform="translate(50,40)"><path d="M15 70l55-30 130 20-55 30z" fill="#7b858c"/><path d="M15 70v36l130 23V90z" fill="#3c4850"/><path d="M145 90l55-30v37l-55 32z" fill="#a3aeb6"/><path d="M15 70l28 5v37l-28-6zm105 15l25 5v39l-25-5z" fill="#b9c5cd"/><text x="70" y="100" fill="#f0f4f6" font-family="Arial" font-size="15" transform="rotate(9 70 100)">472</text></g></svg>';return `<svg viewBox="0 0 320 210" aria-label="示例封装"><g fill="#bd9132" stroke="#9f7720"><rect x="${isIC?85:65}" y="73" width="${isIC?150:62}" height="70" rx="2"/>${isIC?'': '<rect x="193" y="73" width="62" height="70" rx="2"/>'}</g><g stroke="#8ba3b3" stroke-width="1" fill="none"><path d="M65 167h190m-190-5v10m190-10v10M65 55v-9h190v9"/><rect x="105" y="67" width="110" height="82" stroke="#c8a75b" stroke-dasharray="4 3"/></g><g fill="#8699a7" font-family="Arial" font-size="11"><text x="149" y="185">1.60</text><text x="91" y="112">1</text><text x="218" y="112">2</text></g></svg>`;}
function drawArt(){$('drawing').innerHTML=art(tab);const svg=$('drawing').querySelector('svg');if(svg)svg.style.transform='scale('+zoom+')';$('zoomlabel').textContent=Math.round(zoom*100)+'%';$('canvaslabel').textContent=tab==='3d'?'3D 示意 · 正式版使用器件关联模型':'尺寸单位 mm · 示例预览';}
function details(){const r=selected;const df=applied?families[applied.family]:families[family];$('cid').textContent=r?r[0]:'未选择器件';$('detailstock').textContent=r?'库存 '+r[7].toLocaleString():'';$('model').textContent=r?r[1]:'请选择一个器件';$('brand').textContent=r?r[2]+' · '+df.sub:'查询后单击结果，查看封装与参数';$('specs').innerHTML=r?[[df.value,r[4]],['封装',r[3]],[applied?.family==='ic'?'核心配置':'精度',r[5]],[df.power,r[6]]].map(([k,v])=>`<div><span>${k}</span>${v}</div>`).join(''):'';$('place').disabled=!r;$('datasheet').style.visibility=r?'visible':'hidden';if(!r){detailSeq++;$('previewwait').style.display='none';$('drawing').innerHTML='';return;}preview();}
function preview(){if(!selected)return;const seq=++detailSeq;$('previewwait').style.display='flex';setTimeout(()=>{if(seq!==detailSeq)return;drawArt();$('previewwait').style.display='none';},650);}
function place(){if(!selected)return;const r=selected;startTask('正在准备 '+r[0],'读取符号 → 准备放置库 → 等待 Capture（模拟流程）',null);$('place').disabled=true;setTimeout(()=>{$('place').disabled=!selected;stopTask();inform('模拟放置已准备','正式版此时切回原理图，器件跟随光标；原型不会发送放置请求。');},1800);}
$('query').onclick=query;$('keyword').oninput=chips;$('keyword').onkeydown=e=>{if(e.key==='Enter')query();};$('more').onclick=()=>{const open=$('extra').classList.toggle('open');$('more').textContent=open?'收起参数 ↑':'更多参数 ↓';};$('mobilecategory').onchange=e=>changeFamily(e.target.value);$('clearfilters').onclick=()=>{Object.keys(draft).forEach(k=>draft[k]='');fields();};$('reset').onclick=()=>{$('keyword').value='';Object.keys(draft).forEach(k=>draft[k]='');fields();};$('cancel').onclick=()=>{if(task&&task.cancel)task.cancel();};$('sort').onchange=draw;$('next').onclick=()=>{page++;draw();};$('prev').onclick=()=>{page--;draw();};$('place').onclick=place;$('datasheet').onclick=e=>{e.preventDefault();inform('数据手册打开示意','正式版打开当前器件关联的 PDF；此原型不访问外部资料。');};document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;document.querySelectorAll('[data-tab]').forEach(x=>x.classList.toggle('active',x===b));zoom=1;preview();});$('zoomin').onclick=()=>{zoom=Math.min(zoom+.25,3);drawArt();};$('zoomout').onclick=()=>{zoom=Math.max(zoom-.25,.5);drawArt();};$('fit').onclick=()=>{zoom=1;drawArt();};$('large').onclick=()=>{if(!selected)return;$('largedrawing').innerHTML=art(tab);$('largetitle').textContent=selected[0]+' · '+({footprint:'PCB 封装',symbol:'原理图符号','3d':'3D 示意模型'}[tab]);$('modal').classList.add('open');$('closelarge').focus();};function close(){$('modal').classList.remove('open');$('large').focus();}$('closelarge').onclick=close;$('modal').onclick=e=>{if(e.target===$('modal'))close();};document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('modal').classList.contains('open'))close();});
categories();fields();rows=families.resistor.rows.filter(r=>r[4]==='4.7kΩ'&&r[3]==='0603');applied={family,keyword:'4.7K',draft:{...draft},signature:JSON.stringify({family,keyword:'4.7K',draft}),label:'贴片电阻 · 4.7kΩ · 0603（示例）'};selected=rows[0];$('applied').textContent=applied.label;draw();details();chips();
})();
